/**
 * Deterministic plain-English rendering.
 *
 * People approve this text, not the JSON. It is generated by code, never by
 * a model, so what people read is exactly what will run.
 */
import { authorizationAmount, formatCents, maxFee } from "./fees.js";
import type { MachineEvent, MachineState, Transfer } from "./interpreter.js";
import type { Clause, ContractIR, Guarantee, Literal, MoneyAction, Trigger } from "./ir.js";

export function formatHours(h: number): string {
  const plural = (n: number, w: string) => `${n} ${w}${n === 1 ? "" : "s"}`;
  if (h < 24) return plural(h, "hour");
  const d = Math.floor(h / 24);
  const r = h % 24;
  return r === 0 ? plural(d, "day") : `${plural(d, "day")} ${plural(r, "hour")}`;
}

const q = (s: string) => `“${s}”`;

function evidenceLabel(ir: ContractIR, id: string | null): string {
  return q(ir.evidence.find((e) => e.id === id)?.label ?? String(id));
}

function deadline(ir: ContractIR, id: string | null) {
  return ir.deadlines.find((d) => d.id === id);
}

function deadlineLabel(ir: ContractIR, id: string | null): string {
  return q(deadline(ir, id)?.label ?? String(id));
}

function joinAnd(parts: string[]): string {
  if (parts.length <= 1) return parts.join("");
  return `${parts.slice(0, -1).join(", ")} and ${parts[parts.length - 1]}`;
}

export function describeLiteral(ir: ContractIR, l: Literal): string {
  const e = evidenceLabel(ir, l.evidence);
  const d = deadlineLabel(ir, l.deadline);
  switch (l.kind) {
    case "submitted":
      return l.negate ? `${e} has not been submitted` : `${e} has been submitted`;
    case "submitted_before":
      return l.negate ? `${e} was not submitted before ${d}` : `${e} was submitted before ${d}`;
    case "accepted":
      return l.negate ? `${e} has not been accepted` : `${e} was accepted`;
    case "rejected":
      return l.negate ? `${e} has not been rejected` : `${e} was rejected`;
    case "deadline_passed":
      return l.negate ? `${d} has not passed yet` : `${d} has passed`;
  }
}

export function describeTrigger(ir: ContractIR, t: Trigger): string {
  switch (t.on) {
    case "activated":
      return "When the contract starts (funding confirmed)";
    case "accepted":
      return `When ${evidenceLabel(ir, t.evidence)} is accepted`;
    case "rejected":
      return `When ${evidenceLabel(ir, t.evidence)} is rejected`;
    case "deadline": {
      const d = deadline(ir, t.deadline);
      return `When ${deadlineLabel(ir, t.deadline)} passes${d ? ` (${formatHours(d.afterHours)} after start)` : ""}`;
    }
  }
}

export function describeAction(ir: ContractIR, a: MoneyAction): string {
  const who = a.op === "release" ? "release" : "refund";
  const to = a.op === "release" ? "to the payee" : "to the funder";
  return a.remaining ? `${who} everything still held ${to}` : `${who} ${formatCents(a.cents ?? 0, ir.currency)} ${to}`;
}

export function describeClause(ir: ContractIR, c: Clause): string {
  const guard = c.guard.length ? `, if ${joinAnd(c.guard.map((l) => describeLiteral(ir, l)))}` : "";
  return `${describeTrigger(ir, c.trigger)}${guard}: ${joinAnd(c.actions.map((a) => describeAction(ir, a)))}.`;
}

export function describeGuarantee(ir: ContractIR, g: Guarantee): string {
  const who = g.party === "payee" ? "The payee" : "The funder";
  const what = g.party === "payee" ? "receives" : "gets back";
  const amount = formatCents(g.atLeastCents, ir.currency);
  if (!g.when.length) return `${who} ${what} at least ${amount} in every outcome.`;
  return `${who} ${what} at least ${amount} whenever ${joinAnd(g.when.map((l) => describeLiteral(ir, l)))}.`;
}

export interface RenderedContract {
  title: string;
  summary: string;
  money: string[];
  deadlines: string[];
  evidence: string[];
  promises: string[];
  rules: string[];
}

export function renderContract(ir: ContractIR, opts: { feeBps?: number } = {}): RenderedContract {
  const feeBps = opts.feeBps ?? 0;
  const fee = maxFee(ir.principalCents, feeBps);
  const money = [
    `Amount at stake: ${formatCents(ir.principalCents, ir.currency)}.`,
    ir.fundingMode === "authorize"
      ? `Funding: the funder approves a PayPal authorization of ${formatCents(authorizationAmount(ir.principalCents, feeBps), ir.currency)}. Money stays on the funder's PayPal account and is captured only when released.`
      : `Funding: the funder pays ${formatCents(authorizationAmount(ir.principalCents, feeBps), ir.currency)} into escrow up front. It is held until released or refunded.`,
    feeBps > 0
      ? `Platform fee: ${(feeBps / 100).toFixed(2)}% of what is actually released (at most ${formatCents(fee, ir.currency)}). Nothing is charged on refunds.`
      : "No platform fee.",
    `Challenge window: after the AI examiner passes a submission, the funder has ${formatHours(ir.challengeWindowHours)} to object before it counts as accepted.`,
  ];
  return {
    title: ir.title,
    summary: ir.summary,
    money,
    deadlines: [...ir.deadlines]
      .sort((a, b) => a.afterHours - b.afterHours)
      .map((d) => `${q(d.label)}: ${formatHours(d.afterHours)} after the contract starts.`),
    evidence: ir.evidence.map(
      (e) => `${q(e.label)} (${e.kind}). Accepted when: ${e.criteria.map((c) => c.replace(/\.$/, "")).join("; ")}.`,
    ),
    promises: ir.guarantees.map((g) => describeGuarantee(ir, g)),
    rules: ir.clauses.map((c) => describeClause(ir, c)),
  };
}

export function narrateEvent(ir: ContractIR, ev: MachineEvent, after: MachineState): string {
  switch (ev.type) {
    case "activate":
      return `Funding is confirmed and the contract starts with ${formatCents(after.heldCents + after.releasedCents + after.refundedCents, ir.currency)} held.`;
    case "submit": {
      const e = after.evidence.find((x) => x.id === ev.evidence);
      const next = e?.before[0];
      return `The payee submits ${evidenceLabel(ir, ev.evidence)}${next ? ` before ${deadlineLabel(ir, next)}` : ""}.`;
    }
    case "accept":
      return `The review accepts ${evidenceLabel(ir, ev.evidence)}.`;
    case "reject":
      return `The review rejects ${evidenceLabel(ir, ev.evidence)}.`;
    case "deadline": {
      const d = deadline(ir, ev.deadline);
      return `${deadlineLabel(ir, ev.deadline)} passes${d ? ` (${formatHours(d.afterHours)} after start)` : ""}.`;
    }
    case "release_all":
      return "The funder releases everything still held to the payee.";
    case "refund_all":
      return "The payee returns everything still held to the funder.";
  }
}

export function narrateTransfer(ir: ContractIR, t: Transfer): string {
  const rule = t.clauseId ? ir.clauses.find((c) => c.id === t.clauseId) : undefined;
  const by = rule ? `Rule ${q(rule.label)}` : "Consent exit";
  return `${by} ${t.op === "release" ? "releases" : "refunds"} ${formatCents(t.cents, ir.currency)} ${t.op === "release" ? "to the payee" : "to the funder"}.`;
}
